"""Regenerate the eight SDLC phase notebooks (01-08) under notebooks/.

"Notebooks as code": the cell *sources* below are the reviewable source of
truth, so the phase notebooks can be regenerated deterministically and diffed
as plain text in git.  Run:  python tools/build_notebooks.py

Important:
  * This writes *skeletons* — code + markdown but no execution outputs. After
    regenerating, run the notebooks (e.g. `jupyter nbconvert --execute`) to
    refresh the committed outputs.
  * Notebook 09 (mlops_toolkit) and every *_basics notebook are maintained as
    executed notebooks and are NOT produced by this script.
"""

from __future__ import annotations

from pathlib import Path

import nbformat as nbf

OUT = Path(__file__).resolve().parents[1] / "notebooks"
OUT.mkdir(parents=True, exist_ok=True)


def build(name: str, cells: list[tuple[str, str]]) -> None:
    """Write notebook `name` from a list of (kind, source) cells (kind is 'md' or 'code')."""
    nb = nbf.v4.new_notebook()
    nb.metadata = {"kernelspec": {"display_name": "Python 3", "language": "python",
                                  "name": "python3"}}
    nb.cells = [nbf.v4.new_markdown_cell(src) if kind == "md"
                else nbf.v4.new_code_cell(src) for kind, src in cells]
    path = OUT / name
    nbf.write(nb, path)
    print(f"wrote {path.relative_to(OUT.parent)}  ({len(cells)} cells)")


